            return { aBefore, bBefore, cBefore, aAfter, bAfter, cAfter }
          })),
        Then('child A count increased (restarted)')((s) =>
          Effect.sync(() => {
            expect(s.result.aAfter).toBeGreaterThan(s.result.aBefore)
          })
        ),
        And('child B count increased (entire tail restarted)')((s) =>
          Effect.sync(() => {
            expect(s.result.bAfter).toBeGreaterThan(s.result.bBefore)
          })
        ),
        And('child C count increased (entire tail restarted)')((s) =>
          Effect.sync(() => {
            expect(s.result.cAfter).toBeGreaterThan(s.result.cBefore)
          })
        ),
      ),
    )

    scenario(
      'Last child failure restarts only last child',
      Gherkin.Do.pipe(
        Given('three counter refs')('counters', () => Effect.all({ a: Ref.make(0), b: Ref.make(0), c: Ref.make(0) })),
        Given('a pause flag for A')('pauseA', () => Ref.make(false)),
        Given('a pause flag for B')('pauseB', () => Ref.make(false)),
        Given('a fail-once flag for C')('failOnceC', () => Ref.make(false)),
        When('child C fails in a restForOne supervisor')('result', (s) =>
          Effect.gen(function*() {
            const childA = Daemon.poll({
              name: 'A',
              work: Effect.gen(function*() {
                const shouldPause = yield* Ref.get(s.pauseA)
                if (!shouldPause) {
                  yield* Ref.update(s.counters.a, (n) => n + 1)
                }
                return void 0
              }),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const childB = Daemon.poll({
              name: 'B',
              work: Effect.gen(function*() {
                const shouldPause = yield* Ref.get(s.pauseB)
                if (!shouldPause) {
                  yield* Ref.update(s.counters.b, (n) => n + 1)
                }
                return void 0
              }),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const childC = Daemon.poll({
              name: 'C',
              work: Effect.gen(function*() {
                yield* Ref.update(s.counters.c, (n) => n + 1)
                const shouldFail = yield* Ref.get(s.failOnceC)
                if (shouldFail) {
                  return yield* new SimulatedFailure()
                }
                return void 0
              }),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const sup = restForOne({
              name: 'restForOne-last',
              children: [childA, childB, childC],
              supervision: Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.seconds(10)).pipe(
                  Schedule.jittered,
                  Schedule.upTo(Duration.minutes(5)),
                ),
                cooldown: Duration.minutes(30),
              }),
              lock: { mode: 'none' },
            })
            const health = yield* run.supervisor(sup).pipe(Effect.provide(NoopLayer))
            yield* TestClock.adjust(Duration.millis(1))
            yield* health.ready.await

            yield* Ref.set(s.pauseA, true)
            yield* Ref.set(s.pauseB, true)
            yield* TestClock.adjust(Duration.millis(50))

            const aBefore = yield* Ref.get(s.counters.a)
            const bBefore = yield* Ref.get(s.counters.b)

            yield* Ref.set(s.failOnceC, true)
            yield* TestClock.adjust(Duration.millis(100))

            const aAfter = yield* Ref.get(s.counters.a)
            const bAfter = yield* Ref.get(s.counters.b)
            const cAfter = yield* Ref.get(s.counters.c)
            return { aBefore, bBefore, aAfter, bAfter, cAfter }
          })),
        Then('child A count is unchanged (head unaffected)')((s) =>
          Effect.sync(() => {
            expect(s.result.aAfter).toEqual(s.result.aBefore)
          })
        ),
        And('child B count is unchanged (head unaffected)')((s) =>
          Effect.sync(() => {
            expect(s.result.bAfter).toEqual(s.result.bBefore)
          })
        ),
        And('child C count increased (restarted)')((s) =>
          Effect.sync(() => {
            expect(s.result.cAfter).toBeGreaterThan(0)
          })
        ),
      ),
    )

    scenario(
      'Repeated middle failures only restart tail',
      Gherkin.Do.pipe(
        Given('start counters for children')(
          'startCounts',
          () => Effect.all({ a: Ref.make(0), b: Ref.make(0), c: Ref.make(0) }),
        ),
        Given('a tick counter for B')('tickB', () => Ref.make(0)),
        When('child B fails repeatedly in a restForOne supervisor')('result', (s) =>
          Effect.gen(function*() {
            const childA = Daemon.poll({
              name: 'A',
              work: Effect.gen(function*() {
                const n = yield* Ref.updateAndGet(s.startCounts.a, (x) => x + 1)
                if (n > 1) yield* Effect.void
              }),
              interval: Duration.millis(100),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const childB = Daemon.poll({
              name: 'B',
              work: Effect.gen(function*() {
                const n = yield* Ref.updateAndGet(s.tickB, (x) => x + 1)
                if (n === 1) yield* Ref.update(s.startCounts.b, (x) => x + 1)
                if (n % 2 === 0) return yield* new SimulatedFailure()
                return void 0
              }),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const childC = Daemon.poll({
              name: 'C',
              work: Effect.gen(function*() {
                yield* Ref.update(s.startCounts.c, (x) => x + 1)
                yield* Effect.void
              }),
              interval: Duration.millis(100),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const sup = restForOne({
              name: 'restForOne-repeated',
              children: [childA, childB, childC],
              supervision: Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.millis(1)).pipe(Schedule.upTo(Duration.millis(5))),
                cooldown: Duration.minutes(30),
              }),
              lock: { mode: 'none' },
            })
            yield* run.supervisor(sup).pipe(Effect.provide(NoopLayer))
            yield* TestClock.adjust(Duration.millis(500))

            const a = yield* Ref.get(s.startCounts.a)
            const c = yield* Ref.get(s.startCounts.c)
            return { a, c }
          })),
        Then('child A started exactly once')((s) =>
          Effect.sync(() => {
            expect(s.result.a).toBe(1)
          })
        ),
        And('child C restarted at least twice')((s) =>
          Effect.sync(() => {
            expect(s.result.c).toBeGreaterThanOrEqual(2)
          })
        ),
      ),
    )

    scenario(
      'RestForOne with nested supervisor in middle',
      Gherkin.Do.pipe(
        Given('counter refs for nested children')(
          'counters',
          () => Effect.all({ a: Ref.make(0), inner: Ref.make(0), c: Ref.make(0) }),
        ),
        Given('a fail-once flag for inner child')('failOnce', () => Ref.make(false)),
        When('middle child is a nested supervisor whose child fails')('result', (s) =>
          Effect.gen(function*() {
            const innerChild = Daemon.poll({
              name: 'inner-B',
              work: Effect.gen(function*() {
                yield* Ref.update(s.counters.inner, (n) => n + 1)
                const shouldFail = yield* Ref.get(s.failOnce)
                if (shouldFail) {
                  return yield* new SimulatedFailure()
                }
                return void 0
              }),
              interval: Duration.millis(100),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const innerSup = oneForOne({
              name: 'inner-sup',
              children: [innerChild],
              supervision: Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.seconds(10)).pipe(
                  Schedule.jittered,
                  Schedule.upTo(Duration.minutes(5)),
                ),
                cooldown: Duration.minutes(30),
              }),
              lock: { mode: 'none' },
            })
            const childA = Daemon.poll({
              name: 'A',
              work: Ref.update(s.counters.a, (n) => n + 1),
              interval: Duration.millis(100),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const childC = Daemon.poll({
              name: 'C',
              work: Ref.update(s.counters.c, (n) => n + 1),
              interval: Duration.millis(100),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const sup = restForOne({
              name: 'restForOne-nested',
              children: [childA, innerSup, childC],
              supervision: Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.seconds(10)).pipe(
                  Schedule.jittered,
                  Schedule.upTo(Duration.minutes(5)),
                ),
                cooldown: Duration.minutes(30),
              }),
              lock: { mode: 'none' },
            })
            const health = yield* run.supervisor(sup).pipe(Effect.provide(NoopLayer))
            yield* TestClock.adjust(Duration.millis(1))
            yield* health.ready.await

            const cBefore = yield* Ref.get(s.counters.c)

            yield* Ref.set(s.failOnce, true)
            yield* TestClock.adjust(Duration.millis(300))

            const cAfter = yield* Ref.get(s.counters.c)
            return { cBefore, cAfter }
          })),
        Then('child C count increased (tail including nested subtree restarted)')((s) =>
          Effect.sync(() => {
            expect(s.result.cAfter).toBeGreaterThan(s.result.cBefore)
          })
        ),
      ),
    )
  })

Feature('Uniform Supervisor Behavior')
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenarioOutline }) => {
    scenarioOutline(
      '<strategy> ready opens when all children ready',
      [
        { strategy: 'oneForOne', makeSupervisor: oneForOne },
        { strategy: 'oneForAll', makeSupervisor: oneForAll },
        { strategy: 'restForOne', makeSupervisor: restForOne },
      ],
      (row) =>
        Gherkin.Do.pipe(
          Given('a noop counter ref')('counter', () => Ref.make(0)),
          When('a <strategy> supervisor runs with 1 child')('health', (s) =>
            Effect.gen(function*() {
              const child = Daemon.poll({
                name: 'noop',
                work: Ref.update(s.counter, (n) => n + 1),
                interval: Duration.millis(1),
                tick: { tickTimeout: Duration.seconds(90) },
                lock: { mode: 'none' },
              })
              const sup = row.makeSupervisor({
                name: `${row.strategy}-ready-outline`,
                children: [child],
                lock: { mode: 'none' },
                supervision: Supervision.custom({
                  intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                  backoff: Schedule.exponential(Duration.seconds(10)).pipe(
                    Schedule.jittered,
                    Schedule.upTo(Duration.minutes(5)),
                  ),
                  cooldown: Duration.minutes(30),
                }),
              })
              const health = yield* run.supervisor(sup).pipe(Effect.provide(NoopLayer))
              yield* TestClock.adjust(Duration.millis(10))
              return { health }
            })),
          Then('supervisor ready is open')((s) => s.health.health.ready.await),
        ),
    )

    scenarioOutline(
      '<strategy> all poll children ready opens supervisor ready',
      [{ strategy: 'oneForOne' }, { strategy: 'oneForAll' }, { strategy: 'restForOne' }],
      (row) =>
        Gherkin.Do.pipe(
          Given('counter refs for poll children')('counters', () =>
            Effect.all({ a: Ref.make(0), b: Ref.make(0), c: Ref.make(0) })),
          When('supervisor runs with ticking poll children')('health', (s) =>
            Effect.gen(function*() {
              const poll = (name: 'A' | 'B' | 'C', r: Ref.Ref<number>) =>
                Daemon.poll({
                  name,
                  work: Ref.update(r, (n) =>
                    n + 1),
                  interval: Duration.millis(1),
                  tick: { tickTimeout: Duration.seconds(90) },
                  lock: { mode: 'none' },
                })
              const supervision = Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.seconds(10)).pipe(
                  Schedule.jittered,
                  Schedule.upTo(Duration.minutes(5)),
                ),
                cooldown: Duration.minutes(30),
              })
              const sup = Match.value(row.strategy).pipe(
                Match.when('oneForOne', () =>
                  oneForOne({
                    name: `${row.strategy}-multi-ready`,
                    children: [poll('A', s.counters.a), poll('B', s.counters.b)],
                    supervision,
                    lock: { mode: 'none' },
                  })),
                Match.when('oneForAll', () =>
                  oneForAll({
                    name: `${row.strategy}-multi-ready`,
                    children: [poll('A', s.counters.a), poll('B', s.counters.b)],
                    supervision,
                    lock: { mode: 'none' },
                  })),
                Match.when('restForOne', () =>
                  restForOne({
                    name: `${row.strategy}-multi-ready`,
                    children: [poll('A', s.counters.a), poll('B', s.counters.b), poll('C', s.counters.c)],
                    supervision,
                    lock: { mode: 'none' },
                  })),
                Match.exhaustive,
              )
              const health = yield* run.supervisor(sup).pipe(Effect.provide(NoopLayer))
              yield* TestClock.adjust(Duration.millis(10))
              return { health, counters: s.counters }
            })),
          Then('supervisor ready is open')((s) => s.health.health.ready.await),
          And('all started poll children ticked at least once')((s) =>
            Effect.gen(function*() {
              const a = yield* Ref.get(s.health.counters.a)
              const b = yield* Ref.get(s.health.counters.b)
              expect(a).toBeGreaterThanOrEqual(1)
              expect(b).toBeGreaterThanOrEqual(1)
              yield* Match.value(row.strategy).pipe(
                Match.when('restForOne', () =>
                  Effect.gen(function*() {
                    const c = yield* Ref.get(s.health.counters.c)
                    expect(c).toBeGreaterThanOrEqual(1)
                  })),
                Match.when('oneForOne', () => Effect.void),
                Match.when('oneForAll', () => Effect.void),
                Match.exhaustive,
              )
            })
          ),
        ),
    )

    scenarioOutline(
      '<strategy> reports exhausted on persistent failure',
      [
        { strategy: 'oneForOne', makeSupervisor: oneForOne },
        { strategy: 'oneForAll', makeSupervisor: oneForAll },
        { strategy: 'restForOne', makeSupervisor: restForOne },
      ],
      (row) =>
        Gherkin.Do.pipe(
          Given('a reporter spy')('spy', () => ReporterSpyContext),
          When('a <strategy> supervisor runs with an always-failing child')('result', (s) =>
            Effect.gen(function*() {
              const tickCount = yield* Ref.make(0)
              const child = Daemon.poll({
                name: 'A',
                work: Effect.gen(function*() {
                  const n = yield* Ref.updateAndGet(tickCount, (x) => x + 1)
                  if (n > 1) return yield* new SimulatedFailure()
                  return void 0
                }),
                interval: Duration.millis(1),
                tick: { tickTimeout: Duration.seconds(90) },
                lock: { mode: 'none' },
              })
              const sup = row.makeSupervisor({
                name: `${row.strategy}-exhaust-outline`,
                children: [child],
                lock: { mode: 'none' },
                supervision: Supervision.custom({
                  intensity: new BoundedIntensity({ restarts: 1, window: Duration.seconds(60) }),
                  backoff: Schedule.exponential(Duration.millis(5)).pipe(
                    Schedule.upTo(Duration.millis(50)),
                  ),
                  cooldown: Duration.minutes(30),
                }),
              })
              const reporterLayer = Layer.mergeAll(
                LeaderLock.Noop,
                Layer.succeed(DaemonReporter, s.spy.reporter),
              )
              yield* run.supervisor(sup).pipe(Effect.provide(reporterLayer))
              yield* TestClock.adjust(Duration.millis(500))
              const exhaustions = yield* s.spy.getExhaustions()
              return { exhaustions }
            })),
          Then('exactly 1 exhausted event was reported')((s) =>
            Effect.sync(() => {
              expect(s.result.exhaustions).toHaveLength(1)
              expect(s.result.exhaustions[0]?.name).toBe(`${row.strategy}-exhaust-outline`)
            })
          ),
        ),
    )
  })

src/__tests__/never-surrender.feature.te.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, Layer, Schema as S, TestClock } from 'effect'
import { expect } from 'vitest'
import { DaemonReporter } from '../daemon-reporter.js'
import { Daemon } from '../daemon.js'
import { LeaderLock } from '../leader-lock.js'
import { run } from '../run.js'
import { Supervision } from '../supervision-preset.js'
import { oneForOne } from '../supervisor.js'
import { ReporterSpyContext } from './helpers/reporter-spy.js'

class SimulatedFailure extends S.TaggedError<SimulatedFailure>()('SimulatedFailure', {}) {}

const Feature = makeFeature({ it, layer })

Feature('Leader daemon never surrenders under sustained failure')
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'A persistently failing process is restarted indefinitely regardless of elapsed time',
      Gherkin.Do.pipe(
        Given('a reporter spy is configured')('spy', () => ReporterSpyContext),
        When('a persistently failing supervised process runs')(
          'result',
          (s) =>
            Effect.gen(function*() {
              const child = Daemon.poll({
                name: 'always-fails',
                work: new SimulatedFailure(),
                interval: Duration.millis(10),
                tick: { tickTimeout: Duration.seconds(90) },
                lock: { mode: 'none' },
              })
              const sup = oneForOne({
                name: 'never-surrender-sup',
                children: [child],
                supervision: Supervision.leader(Duration.seconds(30)),
                lock: { mode: 'none' },
              })
              const reporterLayer = Layer.mergeAll(LeaderLock.Noop, Layer.succeed(DaemonReporter, s.spy.reporter))
              yield* run.supervisor(sup).pipe(Effect.provide(reporterLayer))

              yield* TestClock.adjust(Duration.minutes(10))
              const early = (yield* s.spy.getRestarts()).filter((r) => r.name === 'never-surrender-sup').length
              yield* TestClock.adjust(Duration.minutes(30))
              const late = (yield* s.spy.getRestarts()).filter((r) => r.name === 'never-surrender-sup').length
              return { early, late }
            }),
        ),
        Then('the leader restarted the process at least once within the first 10 minutes')((s) =>
          Effect.sync(() => {
            expect(s.result.early).toBeGreaterThan(0)
          })
        ),
        And('the leader continues restarting the process beyond 40 minutes')((s) =>
          Effect.sync(() => {
            expect(s.result.late).toBeGreaterThan(s.result.early)
          })
        ),
      ),
    )
  })

src/__tests__/worker-lifecycle.feature.t.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, Either, Exit, Fiber, Ref, Schedule, Stream, TestClock } from 'effect'
import { expect } from 'vitest'
import { Daemon } from '../daemon.js'
import { allocateWorkerHealth } from '../internal/boot.js'
import { buildWorkerLoop } from '../internal/worker-loop.js'
import { run } from '../run.js'
import { NoopLayer } from './helpers/shared-layers.js'
import { BufferedRef, CounterRef } from './helpers/test-utils.js'

const Feature = makeFeature({ it, layer })

Feature('Poll Worker Lifecycle')
  .withLayer(NoopLayer)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Executes repeatedly on interval',
      Gherkin.Do.pipe(
        Given('a counter')('counterRef', () => CounterRef.make),
        When('a poll worker is started')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'repeater',
              work: CounterRef.increment(s.counterRef),
              interval: Duration.millis(10),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(110))
            return health
          })),
        Then('counter is at least 3')((s) =>
          CounterRef.read(s.counterRef).pipe(
            Effect.flatMap((count) =>
              Effect.sync(() => {
                expect(count).toBeGreaterThanOrEqual(3)
              })
            ),
          )
        ),
      ),
    )

    scenario(
      'Becomes ready after the first successful tick',
      Gherkin.Do.pipe(
        Given('a counter')('counterRef', () => CounterRef.make),
        When('a poll worker is started')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'ready-opener',
              work: CounterRef.increment(s.counterRef),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(5))
            return health
          })),
        Then('ready is open')((s) => s.health.ready.await),
      ),
    )

    scenario(
      'Pauses when pause gate closed, resumes when opened',
      Gherkin.Do.pipe(
        Given('a counter')('counterRef', () => CounterRef.make),
        When('a poll worker is started and paused immediately')('result', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'pausable',
              work: CounterRef.increment(s.counterRef),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(5))
            const countBeforePause = yield* CounterRef.read(s.counterRef)
            yield* health.paused.close
            yield* Effect.yieldNow()
            yield* TestClock.adjust(Duration.millis(50))
            const countWhilePaused = yield* CounterRef.read(s.counterRef)
            expect(countWhilePaused).toBe(countBeforePause)
            yield* health.paused.open
            yield* Effect.yieldNow()
            yield* TestClock.adjust(Duration.millis(50))
            const countAfterResume = yield* CounterRef.read(s.counterRef)
            expect(countAfterResume).toBeGreaterThan(countWhilePaused)
            return { health }
          })),
      ),
    )

    scenario(
      'Worker stops after a tick fails when no retry policy is configured',
      Gherkin.Do.pipe(
        When('a failing poll worker is started')('health', () =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'failer',
              work: Effect.fail('boom'),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(5))
            return health
          })),
        Then('ready stays closed')((s) =>
          s.health.ready.await.pipe(
            Effect.timeout('0 millis'),
            Effect.either,
            Effect.tap((result) =>
              Effect.sync(() => {
                expect(result).toEqual(Either.left(expect.anything()))
              })
            ),
            Effect.asVoid,
          )
        ),
      ),
    )

    scenario(
      'Worker stops when a tick exceeds the default 90s tick timeout',
      Gherkin.Do.pipe(
        When('a slow poll worker is started')('health', () =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'slow',
              work: Effect.sleep(Duration.seconds(100)),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.seconds(91))
            return health
          })),
        Then('ready stays closed')((s) =>
          s.health.ready.await.pipe(
            Effect.timeout('0 millis'),
            Effect.either,
            Effect.tap((result) =>
              Effect.sync(() => {
                expect(result).toEqual(Either.left(expect.anything()))
              })
            ),
            Effect.asVoid,
          )
        ),
      ),
    )

    scenario(
      'Inner retry keeps worker alive on transient failures',
      Gherkin.Do.pipe(
        When('a poll worker with innerRetry is started')('health', () =>
          Effect.gen(function*() {
            const failCounter = yield* Ref.make(0)
            const worker = Daemon.poll({
              name: 'retrying',
              work: Effect.gen(function*() {
                const n = yield* Ref.get(failCounter)
                if (n < 2) {
                  yield* Ref.update(failCounter, (c) => c + 1)
                  return yield* Effect.fail(`failing tick ${n + 1} of 2`)
                }
                return 'ok'
              }),
              interval: Duration.millis(1),
              tickHooks: { innerRetry: Schedule.recurs(2) },
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(50))
            return health
          })),
        Then('ready is open after retry succeeds')((s) => s.health.ready.await),
      ),
    )

    scenario(
      'Worker stops when innerRetry attempts each exceed the per-tick timeout',
      Gherkin.Do.pipe(
        When('a poll worker with short timeout and innerRetry is started')('health', () =>
          Effect.gen(function*() {
            const worker = Daemon.poll({
              name: 'timeout-retry',
              work: Effect.sleep(Duration.seconds(5)),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.millis(100) },
              tickHooks: { innerRetry: Schedule.once },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(300))
            return health
          })),
        Then('ready stays closed after both retry attempts timeout')((s) =>
          s.health.ready.await.pipe(
            Effect.timeout('0 millis'),
            Effect.either,
            Effect.tap((result) =>
              Effect.sync(() => {
                expect(result).toEqual(Either.left(expect.anything()))
              })
            ),
            Effect.asVoid,
          )
        ),
      ),
    )
  })

Feature('Stream Worker Lifecycle')
  .withLayer(NoopLayer)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Drains all elements from source',
      Gherkin.Do.pipe(
        Given('a buffered ref')('buffer', () => BufferedRef.make<number>()),
        When('a stream worker is started')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.stream({
              name: 'drainer',
              stream: Stream.make(1, 2, 3).pipe(
                Stream.tap((n) => BufferedRef.append(s.buffer, n)),
              ),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(10))
            return health
          })),
        Then('buffer contains all elements')((s) =>
          BufferedRef.readAll(s.buffer).pipe(
            Effect.flatMap((items) =>
              Effect.sync(() => {
                expect(items).toEqual([1, 2, 3])
              })
            ),
          )
        ),
      ),
    )

    scenario(
      'Becomes ready on the first emitted element',
      Gherkin.Do.pipe(
        Given('a buffered ref')('buffer', () => BufferedRef.make<number>()),
        When('a stream worker is started')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.stream({
              name: 'ready-on-first',
              stream: Stream.make(1, 2, 3).pipe(
                Stream.tap((n) => BufferedRef.append(s.buffer, n)),
              ),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(10))
            return health
          })),
        Then('ready is open')((s) => s.health.ready.await),
      ),
    )

    scenario(
      'Stream timeout fails when no element arrives within the timeout window',
      Gherkin.Do.pipe(
        When('a stream worker that never emits is started')('result', () =>
          Effect.gen(function*() {
            const health = yield* allocateWorkerHealth('silent-stream')
            const worker = Daemon.stream({
              name: 'silent-stream',
              stream: Stream.fromEffect(Effect.sleep(Duration.seconds(100))),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const loop = buildWorkerLoop(worker, health)
            const fiber = yield* Effect.forkScoped(loop)
            yield* Effect.yieldNow()
            yield* TestClock.adjust(Duration.seconds(91))
            const exit = yield* Fiber.await(fiber)
            return { exit }
          })),
        Then('worker exit is a failure')((s) =>
          Effect.sync(() => {
            expect(Exit.isSuccess(s.result.exit)).toBe(false)
          })
        ),
      ),
    )

    scenario(
      'Stream worker continues running past timeout after first element is received',
      Gherkin.Do.pipe(
        When('a stream worker that emits then blocks is run past timeout')('result', () =>
          Effect.gen(function*() {
            const health = yield* allocateWorkerHealth('long-lived-stream')
            const worker = Daemon.stream({
              name: 'long-lived-stream',
              stream: Stream.make(1).pipe(
                Stream.concat(Stream.fromEffect(Effect.never)),
              ),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const loop = buildWorkerLoop(worker, health)
            const fiber = yield* Effect.forkScoped(loop)
            yield* Effect.yieldNow()
            yield* TestClock.adjust(Duration.seconds(100))
            const result = yield* Fiber.await(fiber).pipe(
              Effect.timeout('0 millis'),
              Effect.either,
            )
            return { stillRunning: Either.isLeft(result) }
          })),
        Then('worker is still running after timeout')((s) =>
          Effect.sync(() => {
            expect(s.result.stillRunning).toBe(true)
          })
        ),
      ),
    )
  })

Feature('Subscription Worker Lifecycle')
  .withLayer(NoopLayer)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Runs acquire when started',
      Gherkin.Do.pipe(
        Given('an acquired ref')('acquiredRef', () => Ref.make(false)),
        When('a subscription worker is started')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.subscription({
              name: 'subscriber',
              acquire: Ref.set(s.acquiredRef, true),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(5))
            const acquired = yield* Ref.get(s.acquiredRef)
            expect(acquired).toBe(true)
            return health
          })),
        Then('ready is open')((s) => s.health.ready.await),
      ),
    )

    scenario(
      'Closing the pause gate does not stop a running subscription',
      Gherkin.Do.pipe(
        Given('an acquired ref')('acquiredRef', () => Ref.make(false)),
        When('a subscription worker is started then gate is closed')('health', (s) =>
          Effect.gen(function*() {
            const worker = Daemon.subscription({
              name: 'paused-subscriber',
              acquire: Ref.set(s.acquiredRef, true),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const health = yield* run.worker(worker)
            yield* TestClock.adjust(Duration.millis(5))
            const acquired = yield* Ref.get(s.acquiredRef)
            expect(acquired).toBe(true)
            yield* health.paused.close
            yield* Effect.yieldNow()
            yield* TestClock.adjust(Duration.millis(5))
            return health
          })),
        Then('ready stays open after gate close')((s) => s.health.ready.await),
      ),
    )
  })

