import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, Layer, Match, Schedule, TestClock } from 'effect'
import { expect } from 'vitest'
import { BoundedIntensity } from '../daemon-policy.schema.js'
import { DaemonReporter } from '../daemon-reporter.js'
import { Daemon } from '../daemon.js'
import { LeaderLock } from '../leader-lock.js'
import { run } from '../run.js'
import { Supervision } from '../supervision-preset.js'
import { oneForAll, oneForOne, restForOne } from '../supervisor.js'
import { ReporterSpyContext } from './helpers/reporter-spy.js'
import { NoopLayer } from './helpers/shared-layers.js'

const Feature = makeFeature({ it, layer })

const stablePoll = (name: string) =>
  Daemon.poll({
    name,
    work: Effect.void,
    interval: Duration.seconds(10),
    tick: { tickTimeout: Duration.seconds(90) },
    lock: { mode: 'none' },
  })

Feature('Per-child restart policy')
  .withLayer(NoopLayer)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario, scenarioOutline }) => {
    scenario(
      'A one-shot task that fails leaves the system operational',
      Gherkin.Do.pipe(
        Given('a one-shot task that always fails')(
          'worker',
          () =>
            Effect.succeed(
              Daemon.poll({
                name: 'one-shot-failer',
                work: Effect.fail('intentional failure'),
                interval: Duration.millis(1),
                tick: { tickTimeout: Duration.seconds(90) },
                child: { restart: 'temporary' },
                lock: { mode: 'none' },
              }),
            ),
        ),
        Given('supervisor runs long enough to tempt naive exhaustion')(
          'supHealth',
          (s) =>
            Effect.gen(function*() {
              const sup = oneForOne({
                name: 'parent',
                children: [s.worker],
                supervision: Supervision.custom({
                  intensity: new BoundedIntensity({ restarts: 1, window: Duration.seconds(1) }),
                  backoff: Schedule.exponential(Duration.millis(10), 1),
                  cooldown: Duration.minutes(30),
                }),
                lock: { mode: 'none' },
              })
              const supHealth = yield* run.supervisor(sup)
              yield* TestClock.adjust(Duration.seconds(2))
              return supHealth
            }),
        ),
        Then('the system is still operational')((s) => s.supHealth.healthy.await),
      ),
    )

    scenario(
      'A flaky task with a stricter restart budget than its parent is honoured',
      Gherkin.Do.pipe(
        Given('a flaky task that disallows any restart at the per-task level')(
          'worker',
          () =>
            Effect.succeed(
              Daemon.poll({
                name: 'no-restart-task',
                work: Effect.fail('intentional failure'),
                interval: Duration.millis(1),
                tick: { tickTimeout: Duration.seconds(90) },
                child: { intensity: { restarts: 0, window: Duration.seconds(60) } },
                lock: { mode: 'none' },
              }),
            ),
        ),
        Given('supervisor is permissive at the parent level')(
          'supHealth',
          (s) =>
            Effect.gen(function*() {
              const sup = oneForOne({
                name: 'permissive-parent',
                children: [s.worker],
                supervision: Supervision.custom({
                  intensity: new BoundedIntensity({ restarts: 1, window: Duration.seconds(1) }),
                  backoff: Schedule.exponential(Duration.millis(10), 1),
                  cooldown: Duration.minutes(30),
                }),
                lock: { mode: 'none' },
              })
              const supHealth = yield* run.supervisor(sup)
              yield* TestClock.adjust(Duration.seconds(2))
              return supHealth
            }),
        ),
        Then('the system is still operational because the per-task budget prevented any restart')((s) =>
          s.supHealth.healthy.await
        ),
      ),
    )

    scenarioOutline(
      '<strategy> <policy> respects per-child policy without group supervisor exhaustion',
      [
        { strategy: 'oneForAll', policy: 'temporary' },
        { strategy: 'oneForAll', policy: 'childBudget' },
        { strategy: 'restForOne', policy: 'temporary' },
        { strategy: 'restForOne', policy: 'childBudget' },
      ] as const,
      (row) => {
        const flaky = Match.value(row.policy).pipe(
          Match.when('temporary', () =>
            Daemon.poll({
              name: `flaky-${row.strategy}-temp`,
              work: Effect.fail('intentional failure'),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              child: { restart: 'temporary' },
              lock: { mode: 'none' },
            })),
          Match.when('childBudget', () =>
            Daemon.poll({
              name: `flaky-${row.strategy}-budget`,
              work: Effect.fail('intentional failure'),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              child: { intensity: { restarts: 0, window: Duration.seconds(60) } },
              lock: { mode: 'none' },
            })),
          Match.exhaustive,
        )

        const children = Match.value(row.strategy).pipe(
          Match.when('oneForAll', () => [flaky, stablePoll(`stable-${row.strategy}-${row.policy}`)]),
          Match.when('restForOne', () => [
            stablePoll(`rest-before-${row.strategy}-${row.policy}`),
            flaky,
            stablePoll(`rest-after-${row.strategy}-${row.policy}`),
          ]),
          Match.exhaustive,
        )

        const supervisorIntensity = Match.value(row.policy).pipe(
          Match.when('temporary', () => ({ restarts: 0, window: Duration.seconds(1) })),
          Match.when('childBudget', () => ({ restarts: 10, window: Duration.seconds(1) })),
          Match.exhaustive,
        )

        return Gherkin.Do.pipe(
          Given('group supervisor under test with reporter spy')(
            'out',
            () =>
              Effect.gen(function*() {
                const spy = yield* ReporterSpyContext
                const reporterLayer = Layer.mergeAll(LeaderLock.Noop, Layer.succeed(DaemonReporter, spy.reporter))
                const supervisorOpts = {
                  name: `group-parent-${row.strategy}-${row.policy}`,
                  children,
                  lock: { mode: 'none' as const },
                  supervision: Supervision.custom({
                    intensity: new BoundedIntensity(supervisorIntensity),
                    backoff: Schedule.exponential(Duration.millis(10), 1),
                    cooldown: Duration.minutes(30),
                  }),
                }

                const sup = Match.value(row.strategy).pipe(
                  Match.when('oneForAll', () => oneForAll(supervisorOpts)),
                  Match.when('restForOne', () => restForOne(supervisorOpts)),
                  Match.exhaustive,
                )
                const supHealth = yield* run.supervisor(sup).pipe(Effect.provide(reporterLayer))
                yield* TestClock.adjust(Duration.seconds(2))
                const exhaustions = yield* spy.getExhaustions()
                const restarts = yield* spy.getRestarts()
                return { supHealth, exhaustions, restarts }
              }),
          ),
          Then('supervisor healthy latch stays open')((s) => s.out.supHealth.healthy.await),
          And('reporter records no supervisor exhaustion events')((s) =>
            Effect.sync(() => {
              expect(s.out.exhaustions).toHaveLength(0)
            })
          ),
          And('reporter records no supervisor restart events')((s) =>
            Effect.sync(() => {
              expect(s.out.restarts).toHaveLength(0)
            })
          ),
        )
      },
    )

    scenario(
      'oneForAll treats omitted child restart policy as permanent and exhausts supervisor',
      Gherkin.Do.pipe(
        When('a group supervisor with default permanent policy and zero restarts budget')(
          'out',
          () =>
            Effect.gen(function*() {
              const spy = yield* ReporterSpyContext
              const reporterLayer = Layer.mergeAll(LeaderLock.Noop, Layer.succeed(DaemonReporter, spy.reporter))
              const worker = Daemon.poll({
                name: 'default-permanent-fail',
                work: Effect.fail('intentional failure'),
                interval: Duration.millis(1),
                tick: { tickTimeout: Duration.seconds(90) },
                lock: { mode: 'none' },
              })
              const sup = oneForAll({
                name: 'default-policy-parent',
                children: [worker],
                supervision: Supervision.custom({
                  intensity: new BoundedIntensity({ restarts: 0, window: Duration.seconds(1) }),
                  backoff: Schedule.exponential(Duration.millis(10), 1),
                  cooldown: Duration.minutes(30),
                }),
                lock: { mode: 'none' },
              })
              const supHealth = yield* run.supervisor(sup).pipe(Effect.provide(reporterLayer))
              yield* TestClock.adjust(Duration.seconds(2))
              const exhaustions = yield* spy.getExhaustions()
              const healthyOpen = yield* supHealth.healthy.await.pipe(
                Effect.timeout('0 millis'),
                Effect.matchEffect({
                  onFailure: () => Effect.succeed(false),
                  onSuccess: () => Effect.succeed(true),
                }),
              )
              return { exhaustions, healthyOpen }
            }),
        ),
        Then('healthy latch closes and supervisor exhaustion is reported')((s) =>
          Effect.sync(() => {
            expect(s.out.healthyOpen).toBe(false)
            expect(s.out.exhaustions.length).toBeGreaterThanOrEqual(1)
          })
        ),
      ),
    )
  })

src/__tests__/intensity.feature.test.ts.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, TestClock } from 'effect'
import { expect } from 'vitest'
import { BoundedIntensity } from '../daemon-policy.schema.js'
import { make } from '../internal/intensity.js'

const Feature = makeFeature({ it, layer })

Feature('Intensity Tracker')
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Events below threshold — not exceeded',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=5, window=60s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 5, window: Duration.seconds(60) })),
        ),
        When('3 events are recorded')(
          'result',
          (s) => Effect.all([s.tracker.record, s.tracker.record, s.tracker.record]),
        ),
        Then('count is 3')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(3)
            })
          ))
        ),
        And('isExceeded is false')((s) =>
          s.tracker.isExceeded.pipe(Effect.flatMap((e) =>
            Effect.sync(() => {
              expect(e).toBe(false)
            })
          ))
        ),
      ),
    )

    scenario(
      'Events above threshold — exceeded',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=3, window=60s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 3, window: Duration.seconds(60) })),
        ),
        When('4 events are recorded')(
          'result',
          (s) => Effect.all([s.tracker.record, s.tracker.record, s.tracker.record, s.tracker.record]),
        ),
        Then('isExceeded is true')((s) =>
          s.tracker.isExceeded.pipe(Effect.flatMap((e) =>
            Effect.sync(() => {
              expect(e).toBe(true)
            })
          ))
        ),
      ),
    )

    scenario(
      'Exactly at threshold — not exceeded',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=3')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 3, window: Duration.seconds(60) })),
        ),
        When('3 events are recorded')(
          'result',
          (s) => Effect.all([s.tracker.record, s.tracker.record, s.tracker.record]),
        ),
        Then('count is 3')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(3)
            })
          ))
        ),
        And('isExceeded is false')((s) =>
          s.tracker.isExceeded.pipe(Effect.flatMap((e) =>
            Effect.sync(() => {
              expect(e).toBe(false)
            })
          ))
        ),
      ),
    )

    scenario(
      'Old events pruned outside window',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=5, window=10s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 5, window: Duration.seconds(10) })),
        ),
        When('an event is recorded')('result', (s) => s.tracker.record),
        And('time advances by 11 seconds')(() => TestClock.adjust(Duration.seconds(11))),
        Then('count is 0')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(0)
            })
          ))
        ),
      ),
    )

    scenario(
      'Multiple records within window',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=2')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 2, window: Duration.seconds(60) })),
        ),
        When('3 events are recorded')(
          'result',
          (s) => Effect.all([s.tracker.record, s.tracker.record, s.tracker.record]),
        ),
        Then('count is 3')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(3)
            })
          ))
        ),
        And('isExceeded is true')((s) =>
          s.tracker.isExceeded.pipe(Effect.flatMap((e) =>
            Effect.sync(() => {
              expect(e).toBe(true)
            })
          ))
        ),
      ),
    )

    scenario(
      'Event at window boundary',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=5, window=10s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 5, window: Duration.seconds(10) })),
        ),
        When('an event is recorded')('result', (s) => s.tracker.record),
        And('time advances by exactly 10 seconds')(() => TestClock.adjust(Duration.seconds(10))),
        Then('count is 1')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(1)
            })
          ))
        ),
      ),
    )

    scenario(
      'All events expire',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=5, window=1s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 5, window: Duration.seconds(1) })),
        ),
        When('2 events are recorded')('result', (s) => Effect.all([s.tracker.record, s.tracker.record])),
        And('time advances by 2 seconds')(() => TestClock.adjust(Duration.seconds(2))),
        Then('count is 0')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(0)
            })
          ))
        ),
      ),
    )

    scenario(
      'Pruning reflects correct remaining count as window slides',
      Gherkin.Do.pipe(
        Given('a tracker with restarts=3, window=5s')(
          'tracker',
          () => make(new BoundedIntensity({ restarts: 3, window: Duration.seconds(5) })),
        ),
        When('3 events are recorded')(
          'result',
          (s) => Effect.all([s.tracker.record, s.tracker.record, s.tracker.record]),
        ),
        And('time advances by 3 seconds')(() => TestClock.adjust(Duration.seconds(3))),
        Then('count is 3')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(3)
            })
          ))
        ),
        And('isExceeded is false at threshold boundary')((s) =>
          s.tracker.isExceeded.pipe(Effect.flatMap((e) =>
            Effect.sync(() => {
              expect(e).toBe(false)
            })
          ))
        ),
        And('time advances by another 3 seconds')(() => TestClock.adjust(Duration.seconds(3))),
        Then('all events have expired and count is 0')((s) =>
          s.tracker.count.pipe(Effect.flatMap((c) =>
            Effect.sync(() => {
              expect(c).toBe(0)
            })
          ))
        ),
      ),
    )
  })

src/__tests__/lock-primitive-contract.fe.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, Either, Fiber, TestClock } from 'effect'
import { expect } from 'vitest'
import { LockPrimitive, LockPrimitiveError } from '../lock-primitive.js'
import {
  mkBlockingStatefulLockPrimitive,
  mkFailingLockPrimitive,
  mkStatefulLockPrimitive,
} from './helpers/lock-primitive-fakes.js'

const Feature = makeFeature({ it, layer })

Feature('Lock Primitive Contract')
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Acquire free lock',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('no lock is held for key "task-1"')(() => Effect.void),
        When('the caller attempts to acquire key "task-1" within a scope')(
          'results',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                const first = yield* prim.tryAcquire('task-1')
                const second = yield* prim.tryAcquire('task-1')
                return { first, second }
              }),
            ),
        ),
        Then('the return value is true')((s) =>
          Effect.sync(() => {
            expect(s.results.first).toBe(true)
          })
        ),
        And('acquiring the same key again from the same scope also returns true')((s) =>
          Effect.sync(() => {
            expect(s.results.second).toBe(true)
          })
        ),
      ),
    )

    scenario(
      'Acquire held lock',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('the lock key "task-1" is held by another caller')('holder', () =>
          Effect.gen(function*() {
            const prim = yield* LockPrimitive
            const fiber = yield* Effect.fork(
              Effect.scoped(
                Effect.gen(function*() {
                  yield* prim.tryAcquire('task-1')
                  return yield* Effect.never
                }),
              ),
            )
            yield* Effect.yieldNow()
            return fiber
          })),
        When('the caller attempts to acquire key "task-1" within a scope')(
          'acquired',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                return yield* prim.tryAcquire('task-1')
              }),
            ),
        ),
        Then('the return value is false')((s) =>
          Effect.sync(() => {
            expect(s.acquired).toBe(false)
          })
        ),
        And('the holder fiber is interrupted')((s) => Fiber.interrupt(s.holder)),
      ),
    )

    scenario(
      'Release on scope close',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('the caller holds key "task-1" within a scope that closes normally')(() =>
          Effect.scoped(
            Effect.gen(function*() {
              const prim = yield* LockPrimitive
              yield* prim.tryAcquire('task-1')
            }),
          )
        ),
        When('another caller attempts to acquire key "task-1"')(
          'acquired',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                return yield* prim.tryAcquire('task-1')
              }),
            ),
        ),
        Then('the acquisition succeeds')((s) =>
          Effect.sync(() => {
            expect(s.acquired).toBe(true)
          })
        ),
      ),
    )

    scenario(
      'Release on scope failure',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('the caller holds key "task-1" within a scope that fails')(() =>
          Effect.scoped(
            Effect.gen(function*() {
              const prim = yield* LockPrimitive
              yield* prim.tryAcquire('task-1')
              return yield* Effect.fail('intentional')
            }),
          ).pipe(Effect.catchAll(() => Effect.void))
        ),
        When('another caller attempts to acquire key "task-1"')(
          'acquired',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                return yield* prim.tryAcquire('task-1')
              }),
            ),
        ),
        Then('the acquisition succeeds')((s) =>
          Effect.sync(() => {
            expect(s.acquired).toBe(true)
          })
        ),
      ),
    )

    scenario(
      'Release on scope interruption',
      { layer: mkBlockingStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('a fiber holds key "task-1" via a blocking primitive')('holder', () =>
          Effect.fork(
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                yield* prim.tryAcquire('task-1')
                return yield* Effect.never
              }),
            ),
          )),
        When('the fiber is interrupted')('interrupted', (s) => Fiber.interrupt(s.holder)),
        Then('the lock for key "task-1" is released')((_s) =>
          Effect.scoped(
            Effect.gen(function*() {
              const prim = yield* LockPrimitive
              return yield* prim.tryAcquire('task-1')
            }),
          ).pipe(
            Effect.flatMap((acquired) =>
              Effect.sync(() => {
                expect(acquired).toBe(true)
              })
            ),
          )
        ),
      ),
    )

    scenario(
      'Key independence',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('no locks are held')(() => Effect.void),
        When('the caller acquires key "a" within a scope')(
          'a',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                return yield* prim.tryAcquire('a')
              }),
            ),
        ),
        When('the caller acquires key "b" within the same scope')(
          'b',
          () =>
            Effect.scoped(
              Effect.gen(function*() {
                const prim = yield* LockPrimitive
                return yield* prim.tryAcquire('b')
              }),
            ),
        ),
        Then('both acquire return true')((s) =>
          Effect.sync(() => {
            expect(s.a).toBe(true)
            expect(s.b).toBe(true)
          })
        ),
      ),
    )

    scenario(
      'Primitive infrastructure failure',
      { layer: mkFailingLockPrimitive },
      Gherkin.Do.pipe(
        Given('the underlying lock infrastructure is unavailable')(() => Effect.void),
        When('the caller attempts to acquire any key')(
          'error',
          () =>
            Effect.either(
              Effect.scoped(
                Effect.gen(function*() {
                  const prim = yield* LockPrimitive
                  return yield* prim.tryAcquire('any-key')
                }),
              ),
            ),
        ),
        Then('the call surfaces an infrastructure failure for the requested key')((s) =>
          Effect.sync(() => {
            expect(s.error).toEqual(
              Either.left(new LockPrimitiveError({ key: 'any-key', cause: 'infrastructure unavailable' })),
            )
          })
        ),
      ),
    )

    scenario(
      'Non-blocking contention returns false',
      { layer: mkStatefulLockPrimitive },
      Gherkin.Do.pipe(
        Given('the lock key "task-1" is held by another caller')('holder', () =>
          Effect.gen(function*() {
            const prim = yield* LockPrimitive
            const fiber = yield* Effect.fork(
              Effect.scoped(
                Effect.gen(function*() {
                  yield* prim.tryAcquire('task-1')
                  return yield* Effect.never
                }),
              ),
            )
            yield* Effect.yieldNow()
            return fiber
          })),
        When('another caller attempts to acquire key "task-1" with a timeout')(
          'result',
          () =>
            Effect.either(
              Effect.scoped(
                Effect.gen(function*() {
                  const prim = yield* LockPrimitive
                  return yield* prim.tryAcquire('task-1')
                }),
              ).pipe(Effect.timeout(Duration.seconds(1))),
            ),
        ),
        Then('the acquisition returns false within the timeout')((s) =>
          Effect.sync(() => {
            expect(s.result).toEqual(Either.right(false))
          })
        ),
        And('the holder fiber is interrupted')((s) => Fiber.interrupt(s.holder)),
      ),
    )
  })

src/__tests__/leader-lock-contract.featu.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Duration, Effect, Either, Fiber, Layer, Option, TestClock } from 'effect'
import { expect } from 'vitest'
import { LeaderLock } from '../leader-lock.js'
import { LeaderLockFromPrimitive } from '../lock-primitive.js'
import { mkFailingLockPrimitive, mkStatefulLockPrimitive } from './helpers/lock-primitive-fakes.js'

const Feature = makeFeature({ it, layer })

const LeaderLockFromStatefulPrimitive = Layer.provide(LeaderLockFromPrimitive, mkStatefulLockPrimitive)
const LeaderLockFromFailingPrimitive = Layer.provide(LeaderLockFromPrimitive, mkFailingLockPrimitive)

Feature('LeaderLock Contract')
  .withLayer(LeaderLockFromStatefulPrimitive)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'Acquire free lock and run work',
      Gherkin.Do.pipe(
        Given('no lock is held for key "task-1"')(() => Effect.void),
        When('a caller acquires the lock on key "task-1" and runs successful work')(
          'result',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              return yield* lock.withLock('task-1', Effect.succeed(42))
            }),
        ),
        Then('the result is Some(result)')((s) =>
          Effect.sync(() => {
            expect(s.result).toEqual(Option.some(42))
          })
        ),
        And('after completion, key "task-1" is available again')(() =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            const out = yield* lock.withLock('task-1', Effect.succeed('again'))
            expect(out).toEqual(Option.some('again'))
          })
        ),
      ),
    )

    scenario(
      'Cannot acquire already-held lock',
      Gherkin.Do.pipe(
        Given('a fiber holds the lock for key "task-1"')('holder', () =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            const fiber = yield* Effect.fork(lock.withLock('task-1', Effect.never))
            yield* Effect.yieldNow()
            return fiber
          })),
        When('a second caller attempts to acquire the same lock on key "task-1"')(
          'result',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              return yield* lock.withLock('task-1', Effect.succeed('noop'))
            }),
        ),
        Then('the result is None')((s) =>
          Effect.sync(() => {
            expect(s.result).toEqual(Option.none())
          })
        ),
        And('the holder fiber is interrupted')((s) => Fiber.interrupt(s.holder)),
      ),
    )

    scenario(
      "Mutual exclusion when one fiber holds during another fiber's acquire attempt (S1)",
      Gherkin.Do.pipe(
        Given('no lock is held for key "task"')(() => Effect.void),
        When('one fiber holds the lock across a sleep while another fiber attempts to acquire')(
          'results',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              const holder = yield* Effect.fork(
                lock.withLock('task', Effect.sleep(Duration.millis(10)).pipe(Effect.as('a'))),
              )
              yield* Effect.yieldNow()
              const challenger = yield* Effect.fork(lock.withLock('task', Effect.succeed('b')))
              const b = yield* Fiber.join(challenger)
              yield* TestClock.adjust(Duration.millis(20))
              const a = yield* Fiber.join(holder)
              return { a, b }
            }),
        ),
        Then('exactly one fiber observes Some; the other observes None')((s) =>
          Effect.sync(() => {
            const someCount = [s.results.a, s.results.b].filter(Option.isSome).length
            expect(someCount).toBe(1)
          })
        ),
      ),
    )

    scenario(
      'Acquisition returns immediately without waiting when the key is held (L3)',
      Gherkin.Do.pipe(
        Given('a fiber holds the lock for key "task" indefinitely')('holder', () =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            const fiber = yield* Effect.fork(lock.withLock('task', Effect.never))
            yield* Effect.yieldNow()
            return fiber
          })),
        When('a second caller attempts to acquire the lock on key "task" with a 1-second timeout')(
          'result',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              return yield* Effect.either(
                lock.withLock('task', Effect.succeed('ok')).pipe(Effect.timeout(Duration.seconds(1))),
              )
            }),
        ),
        Then('the call returns None without firing the timeout')((s) =>
          Effect.sync(() => {
            expect(s.result).toEqual(Either.right(Option.none()))
          })
        ),
        And('the holder fiber is interrupted')((s) => Fiber.interrupt(s.holder)),
      ),
    )

    scenario(
      'Key independence',
      Gherkin.Do.pipe(
        Given('no locks are held')(() => Effect.void),
        When('a caller acquires the lock on key "a" and runs work')('a', () =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            return yield* lock.withLock('a', Effect.succeed('a-result'))
          })),
        When('the same caller acquires the lock on key "b" from the same fiber')('b', () =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            return yield* lock.withLock('b', Effect.succeed('b-result'))
          })),
        Then('both return Some')((s) =>
          Effect.sync(() => {
            expect(s.a).toEqual(Option.some('a-result'))
            expect(s.b).toEqual(Option.some('b-result'))
          })
        ),
      ),
    )

    scenario(
      'Release on guarded effect failure',
      Gherkin.Do.pipe(
        When('a caller acquires the lock on key "task-1" but the guarded work fails')(
          'failed',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              return yield* Effect.either(lock.withLock('task-1', Effect.fail('boom')))
            }),
        ),
        Then('the call fails with the inner failure value')((s) =>
          Effect.sync(() => {
            expect(s.failed).toEqual(Either.left('boom'))
          })
        ),
        And('the lock is released for the next caller')(() =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            const out = yield* lock.withLock('task-1', Effect.succeed('ok'))
            expect(out).toEqual(Option.some('ok'))
          })
        ),
      ),
    )

    scenario(
      'Release on guarded effect interruption',
      Gherkin.Do.pipe(
        Given('a fiber holds the lock for key "task-1" indefinitely')(
          'holder',
          () =>
            Effect.gen(function*() {
              const lock = yield* LeaderLock
              const fiber = yield* Effect.fork(lock.withLock('task-1', Effect.never))
              yield* Effect.yieldNow()
              return fiber
            }),
        ),
        When('the fiber is interrupted')('interrupted', (s) => Fiber.interrupt(s.holder)),
        Then('the lock is released')(() =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            const out = yield* lock.withLock('task-1', Effect.succeed('ok'))
            expect(out).toEqual(Option.some('ok'))
          })
        ),
      ),
    )

    scenario(
      'Infrastructure error wrapping',
      { layer: LeaderLockFromFailingPrimitive },
      Gherkin.Do.pipe(
        Given('the underlying lock infrastructure is unavailable')(() => Effect.void),
        When('a caller attempts to acquire the lock on key "task-1"')('error', () =>
          Effect.gen(function*() {
            const lock = yield* LeaderLock
            return yield* Effect.either(lock.withLock('task-1', Effect.succeed('noop')))
          })),
        Then('the call surfaces a lock infrastructure failure tagged with key "task-1"')((s) =>
          Effect.sync(() => {
            Either.match(s.error, {
              onLeft: (err) => {
                expect(err).toEqual(
                  expect.objectContaining({
                    _tag: 'LeaderLockInfraError',
                    key: 'task-1',
                  }),
                )
              },
              onRight: () => expect.fail('expected the failing primitive to surface a failure'),
            })
          })
        ),
      ),
    )
  })

src/__tests__/daemon-reporter.feature.te.source:
import { it, layer } from '@systemfsoftware/effect-gherkin-spec'
import { And, Gherkin, Given, makeFeature, Then, When } from '@systemfsoftware/effect-gherkin-spec'
import { Cause, Duration, Effect, Layer, Option, Schedule, TestClock } from 'effect'
import { expect } from 'vitest'
import { BoundedIntensity } from '../daemon-policy.schema.js'
import { DaemonReporter } from '../daemon-reporter.js'
import { Daemon } from '../daemon.js'
import { LeaderLock } from '../leader-lock.js'
import { run } from '../run.js'
import { Supervision } from '../supervision-preset.js'
import { oneForOne } from '../supervisor.js'
import { ReporterSpyContext, SpyLayer } from './helpers/reporter-spy.js'

const Feature = makeFeature({ it, layer })

const NoopHookFeature = makeFeature({ it, layer })

NoopHookFeature('Daemon reporter Noop hook shape')
  .withLayer(DaemonReporter.Noop)
  .body(({ scenario }) => {
    scenario(
      'Noop onRestart and onExhausted return finishable Effects',
      Gherkin.Do.pipe(
        Given('the noop reporter service')('_', () => Effect.void),
        When('both hooks are invoked')('_', () =>
          Effect.gen(function*() {
            const reporter = yield* DaemonReporter
            const restartEff = reporter.onRestart('noop-check', Cause.empty)
            const exhaustedEff = reporter.onExhausted('noop-check', Cause.empty)
            expect(Effect.isEffect(restartEff)).toBe(true)
            expect(Effect.isEffect(exhaustedEff)).toBe(true)
            yield* Effect.all([restartEff, exhaustedEff], { concurrency: 'unbounded' })
          })),
        Then('no failure is raised')((_s) => Effect.void),
      ),
    )
  })

Feature('Reporter Observability').withScenarioLayer(SpyLayer).body(({ scenario }) => {
  scenario(
    'Noop reporter succeeds silently',
    Gherkin.Do.pipe(
      Given('a noop reporter')('noop', () => Effect.void),
      When('onRestart is called')('_', (_s) =>
        Effect.gen(function*() {
          const reporter = yield* DaemonReporter
          yield* reporter.onRestart('daemon', Cause.die(new Error('boom')))
        })),
      And('onExhausted is called')((_s) =>
        Effect.gen(function*() {
          const reporter = yield* DaemonReporter
          yield* reporter.onExhausted('daemon', Cause.die(new Error('boom')))
        })
      ),
      Then('no errors are raised')((_s) => Effect.void),
    ),
  )

  scenario(
    'onRestart invoked with correct args',
    Gherkin.Do.pipe(
      Given('a daemon reporter spy')('spy', () => ReporterSpyContext),
      When('onRestart is called with name "my-daemon"')(
        'result',
        (s) => s.spy.reporter.onRestart('my-daemon', Cause.die(new Error('test'))),
      ),
      Then('spy recorded exactly one call with name "my-daemon"')((s) =>
        s.spy.getRestarts().pipe(
          Effect.flatMap((restarts) =>
            Effect.sync(() => {
              expect(restarts).toHaveLength(1)
              expect(restarts[0]?.name).toBe('my-daemon')
            })
          ),
        )
      ),
    ),
  )

  scenario(
    'onExhausted invoked with correct args',
    Gherkin.Do.pipe(
      Given('a daemon reporter spy')('spy', () => ReporterSpyContext),
      When('onExhausted is called with name "test-daemon"')(
        'result',
        (s) => s.spy.reporter.onExhausted('test-daemon', Cause.die(new Error('exhausted'))),
      ),
      Then('spy recorded exactly one exhausted call')((s) =>
        s.spy.getExhaustions().pipe(
          Effect.flatMap((exhaustions) =>
            Effect.sync(() => {
              expect(exhaustions).toHaveLength(1)
              expect(exhaustions[0]?.name).toBe('test-daemon')
            })
          ),
        )
      ),
    ),
  )

  scenario(
    'Multiple events from different daemons',
    Gherkin.Do.pipe(
      Given('a daemon reporter spy')('spy', () => ReporterSpyContext),
      When('onRestart is called for "daemon-a"')(
        'result',
        (s) => s.spy.reporter.onRestart('daemon-a', Cause.die(new Error('error-1'))),
      ),
      And('onExhausted is called for "daemon-b"')((s) =>
        s.spy.reporter.onExhausted('daemon-b', Cause.die(new Error('error-2')))
      ),
      And('onRestart is called for "daemon-a" again')((s) =>
        s.spy.reporter.onRestart('daemon-a', Cause.die(new Error('error-3')))
      ),
      Then('spy recorded 2 restarts and 1 exhausted in order')((s) =>
        Effect.gen(function*() {
          const restarts = yield* s.spy.getRestarts()
          const exhaustions = yield* s.spy.getExhaustions()
          expect(restarts).toHaveLength(2)
          expect(exhaustions).toHaveLength(1)
          expect(restarts[0]?.name).toBe('daemon-a')
          expect(exhaustions[0]?.name).toBe('daemon-b')
          expect(restarts[1]?.name).toBe('daemon-a')
        })
      ),
    ),
  )

  scenario(
    'Per-supervisor hooks fire alongside global',
    Gherkin.Do.pipe(
      Given('a daemon reporter spy')('spy', () => ReporterSpyContext),
      When('onRestart is called for "supervisor-1"')(
        'result',
        (s) => s.spy.reporter.onRestart('supervisor-1', Cause.die(new Error('supervisor-restart'))),
      ),
      Then('spy recorded the restart event')((s) =>
        s.spy.getRestarts().pipe(
          Effect.flatMap((restarts) =>
            Effect.sync(() => {
              expect(restarts).toHaveLength(1)
              expect(restarts[0]?.name).toBe('supervisor-1')
            })
          ),
        )
      ),
    ),
  )
})

Feature('Supervisor exhaustion via DaemonReporter')
  .withLayer(LeaderLock.Noop)
  .withScenarioLayer(TestClock.defaultTestClock)
  .body(({ scenario }) => {
    scenario(
      'persistent child failure exhausts supervisor, closes healthy, and reports onExhausted once',
      Gherkin.Do.pipe(
        Given('noop')('_', () => Effect.void),
        When('a zero-restart supervisor wraps a failing poll worker')('out', () =>
          Effect.gen(function*() {
            const spy = yield* ReporterSpyContext
            const reporterLayer = Layer.mergeAll(LeaderLock.Noop, Layer.succeed(DaemonReporter, spy.reporter))
            const worker = Daemon.poll({
              name: 'persist-fail',
              work: Effect.fail('boom'),
              interval: Duration.millis(1),
              tick: { tickTimeout: Duration.seconds(90) },
              lock: { mode: 'none' },
            })
            const sup = oneForOne({
              name: 'exhaust-sup',
              children: [worker],
              supervision: Supervision.custom({
                intensity: new BoundedIntensity({ restarts: 0, window: Duration.seconds(60) }),
                backoff: Schedule.exponential(Duration.millis(1), 1),
                cooldown: Duration.minutes(30),
              }),
              lock: { mode: 'none' },
            })
            const supHealth = yield* run.supervisor(sup).pipe(Effect.provide(reporterLayer))
            yield* TestClock.adjust(Duration.seconds(2))
            const healthyOpen = yield* supHealth.healthy.await.pipe(
              Effect.timeout('0 millis'),
              Effect.matchEffect({
                onFailure: () => Effect.succeed(false),
                onSuccess: () => Effect.succeed(true),
              }),
            )
            const exhaustions = yield* spy.getExhaustions()
            return { healthyOpen, exhaustions }
          })),
        Then('healthy latch is closed and spy records one exhaustion for the supervisor')((s) =>
          Effect.sync(() => {
            expect(s.out.healthyOpen).toBe(false)
            expect(s.out.exhaustions).toHaveLength(1)
            const exhaustion = Option.getOrThrowWith(
              Option.fromNullable(s.out.exhaustions[0]),
              () => new Error('expected one supervisor exhaustion event'),
            )
            expect(exhaustion.name).toBe('exhaust-sup')
            expect(Cause.isDie(exhaustion.cause)).toBe(true)
          })
        ),
      ),
    )
  })

